const MEM_FEE_FLUSH_WINDOW: MemoryId = MemoryId::new(24);

/// `[operations, insurance, staking]` accrued this window.
type PendingFeeAccrualCell = Scalars<3>;

/// `[fee_flush_window_ns]`.
type FeeFlushWindowCell = Scalars<1>;

/// Word indices into [`PendingFeeAccrualCell`] — named so a reordering is a
