// TEST ONLY — absent from production builds (no --features testing).
// P-VK (POOL-04, gate tests (a′)/(a″)): clock-boundary injection. Sets
// PENDING_VK_ACTIVE_AT to "due now" (1 ns) so the lazy time-gated activation
// path can be exercised in PocketIC, whose simulated time cannot cross a
// scheduled activation inside a call cascade. This endpoint substitutes ONLY
// the passage of time: it does NOT activate the VK (PINNED_VK_HASH /
// PINNED_CIRCUIT_VERSION untouched), does NOT clear the pending state, and
// does NOT bump SECURITY_EPOCH. Returns the pinned VK hash and security epoch
// immediately before and after the write so the caller can prove the
// backdate itself changed nothing else.
#[cfg(feature = "testing")]
#[update]
fn backdate_pending_vk_activation_for_test() -> (BackdatePendingVkProbe, BackdatePendingVkProbe) {
    assert_operator_controller();
    let before = BackdatePendingVkProbe {
        pinned_vk_hash: PINNED_VK_HASH.with(|h| *h.borrow()),
        security_epoch: security_epoch(),
    };
    PENDING_VK_ACTIVE_AT.with(|a| {
        assert!(
            a.borrow().is_some(),
            "backdate_pending_vk_activation_for_test: no pending VK activation scheduled"
        );
        *a.borrow_mut() = Some(1);
    });
    let after = BackdatePendingVkProbe {
        pinned_vk_hash: PINNED_VK_HASH.with(|h| *h.borrow()),
        security_epoch: security_epoch(),
    };
    (before, after)
}

/// TEST ONLY — probe returned by backdate_pending_vk_activation_for_test.
