/// TEST ONLY — seed MANY terminal deposits in one message.
///
/// B12a has to build an already-redacted prefix AT LEAST as large as
/// `MAX_REDACT_SCAN_PER_TICK`, because the starvation it probes only appears
/// once the prefix exceeds one tick's scan budget. Ten thousand individual
/// ingress messages would make that test unrunnable; this seeds them directly,
/// leaving the SHIPPED cap untouched — which is what the row has to bite at.
#[cfg(feature = "testing")]
#[update]
fn inject_terminal_deposits_bulk_for_test(
    start_index: u32,
    count: u32,
    finalized_at_ns: u64,
    depositor: Principal,
) {
    assert_operator_controller();
    for i in 0..count {
        let idx = start_index + i;
        let mut commitment = [0u8; 32];
        commitment[0..4].copy_from_slice(&idx.to_be_bytes());
        commitment[4] = 0xBB; // domain-separate from the single-inject fixtures
        let rec = PendingDeposit {
            note_commitment: commitment,
            private_balance: 0,
            ops_amount: 0,
            insurance_amount: 0,
            staking_amount: Some(0),
            encrypted_payload: Vec::new(),
            depositor: Some(depositor),
            status: DepositStatus::CommitmentRootAccepted { leaf_index: idx as u64, root: [0u8; 32] },
            created_at_ns: time(),
            expected_leaf_index: Some(idx as u64),
            finalized_at_ns: Some(finalized_at_ns),
        };
        PENDING_DEPOSITS.with(|d| d.borrow_mut().insert(CommitmentKey(commitment), rec));
        insert_terminal_deposit_index(finalized_at_ns, commitment);
    }
}

